<?php $items=[['mail-check','Delivered','delivered'],['eye','Opens','open'],['mouse-pointer-click','Clicks','click'],['trending-up','CTR','click'],['activity','Open rate','open'],['circle-off','Bounces','bounce'],['shield-alert','Spam','spam'],['user-minus','Unsubscribes','unsubscribe']];$del=max(1,(int)($metrics['delivered']??0)); ?>
<section class="mt-7"><h2 class="text-xl font-extrabold">Campaign analytics</h2><p class="text-sm text-[#78908c]">Delivery and engagement performance across your workspace.</p><div class="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><?php foreach($items as $i): $value=(int)($metrics[$i[2]]??0); if(in_array($i[1],['CTR','Open rate'],true)) $value=round($value/$del*100,1).'%'; ?><article class="card p-5"><span class="grid h-10 w-10 place-items-center rounded-xl bg-[#d9f4ed] text-mint"><i data-lucide="<?= $i[0] ?>" class="h-5"></i></span><p class="mt-4 text-sm text-[#718c88]"><?= $i[1] ?></p><p class="mt-1 text-3xl font-extrabold"><?= is_int($value)?number_format($value):$value ?></p></article><?php endforeach ?></div><div class="card mt-5 p-6"><h3 class="font-extrabold">Export reports</h3><p class="mt-1 text-sm text-[#78908c]">PDF, CSV and Excel exports are represented in the MVP UI; queued export generation is the next production integration.</p><div class="mt-4 flex gap-3"><?php foreach(['PDF','CSV','Excel'] as $type): ?><button class="btn shadow-soft"><i data-lucide="download" class="h-4"></i><?= $type ?></button><?php endforeach ?></div></div></section>
